INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('2a740ef9-23f9-534b-a45a-3747a30e6531','TEXT','The Tiny Ferry — A Different Day','Sienna liked helping at the river workshop, especially when there was a small job that nobody had planned. One Saturday, Sienna noticed the model ferry was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Sienna decided to stop and look carefully instead of rushing.
