INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('6fcae46b-d8bf-5efe-8445-32b3c3682f44','TEXT','The Tiny Ferry','Sienna liked helping at the river workshop, especially when there was a small job that nobody had planned. One Tuesday, Sienna noticed the model ferry was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Sienna decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('b01d6ff3-8349-5fc4-8174-6cee74148e03','TEXT','The Bicycle Bell Project — A Different Day','Noah liked helping at the bike path, especially when there was a small job that nobody had planned. One Thursday, Noah noticed the bicycle bell was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Noah decided to stop and look carefully instead of rushing.
