INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('0eeb4761-49e6-52a0-a573-db3d9e094344','TEXT','The Bicycle Bell Project','Noah liked helping at the bike path, especially when there was a small job that nobody had planned. One Saturday, Noah noticed the bicycle bell was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Noah decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('7d752bda-ab96-5f6d-bd34-a51be1c55397','TEXT','The Orange Tree Calendar — A Different Day','Ruby liked helping at the school orchard, especially when there was a small job that nobody had planned. One Wednesday, Ruby noticed the fruit calendar was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
