INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('1407b576-0c72-588a-9ecb-dcdf9373c22f','TEXT','The Orange Tree Calendar','Ruby liked helping at the school orchard, especially when there was a small job that nobody had planned. One Thursday, Ruby noticed the fruit calendar was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
