INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('6530d81c-18ea-5667-9a23-dd2b71593c93','TEXT','The Repaired Book','Zoe liked helping at the library corner, especially when there was a small job that nobody had planned. One Friday, Zoe noticed the repair kit was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Zoe decided to stop and look carefully instead of rushing.
